#!/bin/bash

# Ez a script létrehoz egy új mappát, beleírja az összes fájlt a megadott tartalmakkal,
# telepíti a függőségeket, beállítja a szükséges környezeti változókat (interaktívan),
# telepíti a Modal CLI-t ha szükséges, deploy-olja a Modal app-ot,
# majd elindítja a Flask app-ot gunicorn-nal.
# Feltételezi, hogy van Python 3.12+ és pip telepítve. Ha nincs, telepíti őket (Ubuntu/Debian alapú rendszeren).
# Modal-hoz szükség van egy Modal account-re és token-re, amit interaktívan kér be.

set -e  # Kilépés hiba esetén

# Ellenőrizzük a rendszert és telepítjük az alapvető függőségeket
if ! command -v python3 &> /dev/null; then
    echo "Python3 nincs telepítve. Telepítjük (Ubuntu/Debian alapú rendszeren)..."
    sudo apt update
    sudo apt install -y python3 python3-pip python3-venv
fi

if ! command -v pip &> /dev/null; then
    echo "pip nincs telepítve. Telepítjük..."
    sudo apt install -y python3-pip
fi

# Modal CLI telepítése, ha nincs
if ! command -v modal &> /dev/null; then
    echo "Modal CLI nincs telepítve. Telepítjük..."
    pip install modal
fi

# Új mappa létrehozása az app-hoz
APP_DIR="glm46_chat_app"
mkdir -p "$APP_DIR"
cd "$APP_DIR"

# Környezeti változók interaktív beállítása (ha nem léteznek)
echo "Kérjük, adja meg a szükséges környezeti változókat."
read -p "SUPERMEMORY_API_KEY (kötelező): " SUPERMEMORY_API_KEY
export SUPERMEMORY_API_KEY="$SUPERMEMORY_API_KEY"

# Opcionálisak, default értékekkel
read -p "MODEL_ID (default: zai-org/GLM-4.6): " MODEL_ID
export MODEL_ID="${MODEL_ID:-zai-org/GLM-4.6}"

read -p "MAX_MODEL_LEN (default: 200000): " MAX_MODEL_LEN
export MAX_MODEL_LEN="${MAX_MODEL_LEN:-200000}"

read -p "GPU_SPEC (default: B200:8): " GPU_SPEC
export GPU_SPEC="${GPU_SPEC:-B200:8}"

read -p "GPU_MEMORY_UTILIZATION (default: 0.98): " GPU_MEMORY_UTILIZATION
export GPU_MEMORY_UTILIZATION="${GPU_MEMORY_UTILIZATION:-0.98}"

read -p "TENSOR_PARALLEL_SIZE (default: 8): " TENSOR_PARALLEL_SIZE
export TENSOR_PARALLEL_SIZE="${TENSOR_PARALLEL_SIZE:-8}"

read -p "MAX_NUM_SEQS (default: 64): " MAX_NUM_SEQS
export MAX_NUM_SEQS="${MAX_NUM_SEQS:-64}"

read -p "DTYPE (default: auto): " DTYPE
export DTYPE="${DTYPE:-auto}"

read -p "QUANTIZATION (default: awq): " QUANTIZATION
export QUANTIZATION="${QUANTIZATION:-awq}"

read -p "ENABLE_PREFIX_CACHING (default: 1): " ENABLE_PREFIX_CACHING
export ENABLE_PREFIX_CACHING="${ENABLE_PREFIX_CACHING:-1}"

read -p "SUPERMEMORY_TIMEOUT (default: 120.0): " SUPERMEMORY_TIMEOUT
export SUPERMEMORY_TIMEOUT="${SUPERMEMORY_TIMEOUT:-120.0}"

read -p "SUPERMEMORY_MAX_RETRIES (default: 10): " SUPERMEMORY_MAX_RETRIES
export SUPERMEMORY_MAX_RETRIES="${SUPERMEMORY_MAX_RETRIES:-10}"

read -p "SUPERMEMORY_SEARCH_TOP_K (default: 80): " SUPERMEMORY_SEARCH_TOP_K
export SUPERMEMORY_SEARCH_TOP_K="${SUPERMEMORY_SEARCH_TOP_K:-80}"

read -p "SUPERMEMORY_CONTEXT_ITEMS (default: 24): " SUPERMEMORY_CONTEXT_ITEMS
export SUPERMEMORY_CONTEXT_ITEMS="${SUPERMEMORY_CONTEXT_ITEMS:-24}"

read -p "MODAL_APP_NAME (default: glm-46-engine): " MODAL_APP_NAME
export MODAL_APP_NAME="${MODAL_APP_NAME:-glm-46-engine}"

read -p "MODAL_CLS_NAME (default: Engine): " MODAL_CLS_NAME
export MODAL_CLS_NAME="${MODAL_CLS_NAME:-Engine}"

read -p "VLLM_MAX_TOKENS (default: 16384): " VLLM_MAX_TOKENS
export VLLM_MAX_TOKENS="${VLLM_MAX_TOKENS:-16384}"

# Modal token beállítása, ha nincs
if [ -z "$(modal token show)" ]; then
    echo "Modal token nincs beállítva. Kérjük, adja meg:"
    read -p "MODAL_TOKEN_ID: " MODAL_TOKEN_ID
    read -p "MODAL_TOKEN_SECRET: " MODAL_TOKEN_SECRET
    modal token set --token-id "$MODAL_TOKEN_ID" --token-secret "$MODAL_TOKEN_SECRET"
fi

# Fájlok létrehozása

# modal_app.py
cat << 'EOF' > modal_app.py
import os
import modal

MODEL_ID = os.environ.get("MODEL_ID", "zai-org/GLM-4.6")
MAX_MODEL_LEN = int(os.environ.get("MAX_MODEL_LEN", "200000"))
GPU_SPEC = os.environ.get("GPU_SPEC", "B200:8")
GPU_MEMORY_UTILIZATION = float(os.environ.get("GPU_MEMORY_UTILIZATION", "0.98"))
TENSOR_PARALLEL_SIZE = int(os.environ.get("TENSOR_PARALLEL_SIZE", "8"))
MAX_NUM_SEQS = int(os.environ.get("MAX_NUM_SEQS", "64"))
DTYPE = os.environ.get("DTYPE", "auto")
QUANTIZATION = os.environ.get("QUANTIZATION", "awq")
ENABLE_PREFIX_CACHING = os.environ.get("ENABLE_PREFIX_CACHING", "1") == "1"

hf_cache = modal.Volume.from_name("hf-cache", create_if_missing=True)
vllm_cache = modal.Volume.from_name("vllm-cache", create_if_missing=True)

image = (
    modal.Image.from_registry("nvidia/cuda:12.8.0-devel-ubuntu22.04", add_python="3.12")
    .entrypoint([])
    .apt_install("git", "curl", "ca-certificates")
    .pip_install(
        "vllm==0.11.2",
        "transformers==4.49.0",
        "accelerate==1.1.1",
        "huggingface-hub==0.36.0",
        "hf-transfer==0.1.9",
        "safetensors==0.5.2",
    )
    .env(
        {
            "HF_HUB_ENABLE_HF_TRANSFER": "1",
            "HF_HUB_DISABLE_TELEMETRY": "1",
            "TOKENIZERS_PARALLELISM": "false",
            "TRANSFORMERS_NO_ADVISORY_WARNINGS": "1",
        }
    )
)

app = modal.App("glm-46-engine")

@app.cls(
    image=image,
    gpu=GPU_SPEC,
    timeout=60 * 60 * 24,
    container_idle_timeout=60 * 10,
    volumes={
        "/root/.cache/huggingface": hf_cache,
        "/root/.cache/vllm": vllm_cache,
    },
)
class Engine:
    def __init__(self):
        self._ready = False
        self._tokenizer = None
        self._llm = None

    @modal.enter()
    def _load(self):
        from transformers import AutoTokenizer
        from vllm import LLM

        self._tokenizer = AutoTokenizer.from_pretrained(MODEL_ID, trust_remote_code=True)
        llm_kwargs = {
            "model": MODEL_ID,
            "tensor_parallel_size": TENSOR_PARALLEL_SIZE,
            "max_model_len": MAX_MODEL_LEN,
            "dtype": DTYPE,
            "gpu_memory_utilization": GPU_MEMORY_UTILIZATION,
            "trust_remote_code": True,
            "max_num_seqs": MAX_NUM_SEQS,
        }

        if QUANTIZATION:
            llm_kwargs["quantization"] = QUANTIZATION

        if ENABLE_PREFIX_CACHING:
            llm_kwargs["enable_prefix_caching"] = True

        self._llm = LLM(**llm_kwargs)
        self._ready = True

    @modal.method()
    def chat(self, messages, temperature, top_k, max_tokens):
        from vllm import SamplingParams

        if not self._ready:
            raise RuntimeError("Engine not ready")

        if not isinstance(messages, list):
            raise ValueError("messages must be a list")

        prompt = self._tokenizer.apply_chat_template(
            messages,
            tokenize=False,
            add_generation_prompt=True,
        )

        params = SamplingParams(
            temperature=float(temperature),
            top_k=int(top_k),
            top_p=1.0,
            max_tokens=int(max_tokens),
        )

        outputs = self._llm.generate([prompt], params)
        if not outputs or not outputs[0].outputs:
            raise RuntimeError("Empty generation output")

        text = outputs[0].outputs[0].text
        if not isinstance(text, str):
            raise RuntimeError("Invalid generation output type")

        return text
EOF

# main.py
cat << 'EOF' > main.py
import os
import time
import uuid
from flask import Flask, jsonify, render_template, request
import modal
import supermemory
from supermemory import Supermemory

app = Flask(__name__, static_folder="static", template_folder="templates")

SUPERMEMORY_API_KEY = os.environ["SUPERMEMORY_API_KEY"]

SUPERMEMORY_TIMEOUT = float(os.environ.get("SUPERMEMORY_TIMEOUT", "120.0"))
SUPERMEMORY_MAX_RETRIES = int(os.environ.get("SUPERMEMORY_MAX_RETRIES", "10"))
SUPERMEMORY_SEARCH_TOP_K = int(os.environ.get("SUPERMEMORY_SEARCH_TOP_K", "80"))
SUPERMEMORY_CONTEXT_ITEMS = int(os.environ.get("SUPERMEMORY_CONTEXT_ITEMS", "24"))

MODAL_APP_NAME = os.environ.get("MODAL_APP_NAME", "glm-46-engine")
MODAL_CLS_NAME = os.environ.get("MODAL_CLS_NAME", "Engine")

VLLM_MAX_TOKENS = int(os.environ.get("VLLM_MAX_TOKENS", "16384"))

client = Supermemory(
    api_key=SUPERMEMORY_API_KEY,
    timeout=SUPERMEMORY_TIMEOUT,
    max_retries=SUPERMEMORY_MAX_RETRIES,
)

Engine = modal.Cls.from_name(MODAL_APP_NAME, MODAL_CLS_NAME)
engine = Engine()

def _s(x):
    if x is None:
        return ""
    if isinstance(x, str):
        return x
    try:
        return str(x)
    except Exception:
        return ""

def _normalize_history(history):
    if not isinstance(history, list):
        return []
    out = []
    for m in history:
        if not isinstance(m, dict):
            continue
        role = _s(m.get("role")).strip()
        content = _s(m.get("content")).strip()
        if role in ("user", "assistant", "system") and content:
            out.append({"role": role, "content": content})
    return out

def _extract_context(query):
    resp = client.search.execute(q=query, top_k=SUPERMEMORY_SEARCH_TOP_K)
    results = getattr(resp, "results", None)
    if not results:
        return ""
    chunks = []
    for r in results[:SUPERMEMORY_CONTEXT_ITEMS]:
        content = _s(getattr(r, "content", "")).strip()
        if content:
            chunks.append(content)
    if not chunks:
        return ""
    return "\n\n".join(chunks)

def _store_memory(conversation_id, user_text, assistant_text):
    content = user_text + "\n\n" + assistant_text
    client.memories.add(
        content=content,
        metadata={
            "conversation_id": conversation_id,
            "ts_ms": int(time.time() * 1000),
            "type": "chat_turn",
        },
    )

@app.get("/")
def index():
    return render_template("index.html")

@app.post("/api/chat")
def api_chat():
    payload = request.get_json(silent=True) or {}
    user_text = _s(payload.get("message")).strip()
    history = _normalize_history(payload.get("history"))
    conversation_id = _s(payload.get("conversation_id")).strip() or str(uuid.uuid4())

    if not user_text:
        return jsonify({"error": "Empty message"}), 400

    try:
        ctx = _extract_context(user_text)
        system_content = "You are a helpful assistant."
        if ctx:
            system_content = system_content + "\n\nAdditional context:\n" + ctx

        messages = [{"role": "system", "content": system_content}] + history + [{"role": "user", "content": user_text}]
        reply = engine.chat.remote(messages, 1.0, 1, VLLM_MAX_TOKENS)
        _store_memory(conversation_id, user_text, reply)
        return jsonify({"reply": reply, "conversation_id": conversation_id})
    except supermemory.APIConnectionError as e:
        return jsonify({"error": _s(e)}), 502
    except supermemory.RateLimitError as e:
        return jsonify({"error": _s(e)}), 429
    except supermemory.APIStatusError as e:
        return jsonify({"error": _s(e)}), 502
    except Exception as e:
        return jsonify({"error": _s(e)}), 500

@app.get("/health")
def health():
    return jsonify({"ok": True})

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8080)
EOF

