# main.py
cat << 'EOF' > main.py
import os
import time
import uuid
from flask import Flask, jsonify, render_template, request
import modal
import supermemory
from supermemory import Supermemory

app = Flask(__name__, static_folder="static", template_folder="templates")

SUPERMEMORY_API_KEY = os.environ["SUPERMEMORY_API_KEY"]

SUPERMEMORY_TIMEOUT = float(os.environ.get("SUPERMEMORY_TIMEOUT", "120.0"))
SUPERMEMORY_MAX_RETRIES = int(os.environ.get("SUPERMEMORY_MAX_RETRIES", "10"))
SUPERMEMORY_SEARCH_TOP_K = int(os.environ.get("SUPERMEMORY_SEARCH_TOP_K", "80"))
SUPERMEMORY_CONTEXT_ITEMS = int(os.environ.get("SUPERMEMORY_CONTEXT_ITEMS", "24"))

MODAL_APP_NAME = os.environ.get("MODAL_APP_NAME", "glm-46-engine")
MODAL_CLS_NAME = os.environ.get("MODAL_CLS_NAME", "Engine")

VLLM_MAX_TOKENS = int(os.environ.get("VLLM_MAX_TOKENS", "16384"))

client = Supermemory(
    api_key=SUPERMEMORY_API_KEY,
    timeout=SUPERMEMORY_TIMEOUT,
    max_retries=SUPERMEMORY_MAX_RETRIES,
)

Engine = modal.Cls.from_name(MODAL_APP_NAME, MODAL_CLS_NAME)
engine = Engine()

def _s(x):
    if x is None:
        return ""
    if isinstance(x, str):
        return x
    try:
        return str(x)
    except Exception:
        return ""

def _normalize_history(history):
    if not isinstance(history, list):
        return []
    out = []
    for m in history:
        if not isinstance(m, dict):
            continue
        role = _s(m.get("role")).strip()
        content = _s(m.get("content")).strip()
        if role in ("user", "assistant", "system") and content:
            out.append({"role": role, "content": content})
    return out

def _extract_context(query):
    resp = client.search.execute(q=query, top_k=SUPERMEMORY_SEARCH_TOP_K)
    results = getattr(resp, "results", None)
    if not results:
        return ""
    chunks = []
    for r in results[:SUPERMEMORY_CONTEXT_ITEMS]:
        content = _s(getattr(r, "content", "")).strip()
        if content:
            chunks.append(content)
    if not chunks:
        return ""
    return "\n\n".join(chunks)

def _store_memory(conversation_id, user_text, assistant_text):
    content = user_text + "\n\n" + assistant_text
    client.memories.add(
        content=content,
        metadata={
            "conversation_id": conversation_id,
            "ts_ms": int(time.time() * 1000),
            "type": "chat_turn",
        },
    )

@app.get("/")
def index():
    return render_template("index.html")

@app.post("/api/chat")
def api_chat():
    payload = request.get_json(silent=True) or {}
    user_text = _s(payload.get("message")).strip()
    history = _normalize_history(payload.get("history"))
    conversation_id = _s(payload.get("conversation_id")).strip() or str(uuid.uuid4())

    if not user_text:
        return jsonify({"error": "Empty message"}), 400

    try:
        ctx = _extract_context(user_text)
        system_content = "You are a helpful assistant."
        if ctx:
            system_content = system_content + "\n\nAdditional context:\n" + ctx

        messages = [{"role": "system", "content": system_content}] + history + [{"role": "user", "content": user_text}]
        reply = engine.chat.remote(messages, 1.0, 1, VLLM_MAX_TOKENS)
        _store_memory(conversation_id, user_text, reply)
        return jsonify({"reply": reply, "conversation_id": conversation_id})
    except supermemory.APIConnectionError as e:
        return jsonify({"error": _s(e)}), 502
    except supermemory.RateLimitError as e:
        return jsonify({"error": _s(e)}), 429
    except supermemory.APIStatusError as e:
        return jsonify({"error": _s(e)}), 502
    except Exception as e:
        return jsonify({"error": _s(e)}), 500

@app.get("/health")
def health():
    return jsonify({"ok": True})

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8080)
EOF

