const chatEl = document.getElementById("chat");
const inputEl = document.getElementById("input");
const sendEl = document.getElementById("send");
const themeBtn = document.getElementById("themeBtn");
const newBtn = document.getElementById("newBtn");

const state = {
  conversationId: localStorage.getItem("conversation_id") || crypto.randomUUID(),
  history: [],
  busy: false
};

localStorage.setItem("conversation_id", state.conversationId);

const storedTheme = localStorage.getItem("theme") || "dark";
document.body.setAttribute("data-theme", storedTheme);

function setTheme(next) {
  document.body.setAttribute("data-theme", next);
  localStorage.setItem("theme", next);
  const themeColor = next === "light" ? "#ffffff" : "#000000";
  const meta = document.querySelector('meta[name="theme-color"]');
  if (meta) meta.setAttribute("content", themeColor);
}

themeBtn.addEventListener("click", () => {
  const cur = document.body.getAttribute("data-theme");
  setTheme(cur === "dark" ? "light" : "dark");
});

newBtn.addEventListener("click", () => {
  state.history = [];
  state.conversationId = crypto.randomUUID();
  localStorage.setItem("conversation_id", state.conversationId);
  chatEl.innerHTML = "";
  inputEl.focus();
});

function autoGrow() {
  inputEl.style.height = "auto";
  inputEl.style.height = Math.min(inputEl.scrollHeight, 160) + "px";
}

inputEl.addEventListener("input", () => {
  autoGrow();
  sendEl.disabled = state.busy || inputEl.value.trim().length === 0;
});

inputEl.addEventListener("keydown", (e) => {
  if (e.key === "Enter" && !e.shiftKey) {
    e.preventDefault();
    if (!sendEl.disabled) sendMessage();
  }
});

sendEl.addEventListener("click", () => sendMessage());

function append(role, text) {
  const row = document.createElement("div");
  row.className = "msgRow " + role;

  const bubble = document.createElement("div");
  bubble.className = "bubble";
  bubble.textContent = text;

  row.appendChild(bubble);
  chatEl.appendChild(row);
  chatEl.scrollTop = chatEl.scrollHeight;
}

function appendTyping() {
  const row = document.createElement("div");
  const id = "t_" + Date.now().toString(36);
  row.id = id;
  row.className = "msgRow assistant";

  const bubble = document.createElement("div");
  bubble.className = "bubble";

  const typing = document.createElement("div");
  typing.className = "typing";
  typing.innerHTML = '<div class="dot"></div><div class="dot"></div><div class="dot"></div>';

  bubble.appendChild(typing);
  row.appendChild(bubble);
  chatEl.appendChild(row);
  chatEl.scrollTop = chatEl.scrollHeight;
  return id;
}

function removeTyping(id) {
  const el = document.getElementById(id);
  if (el) el.remove();
}

async function sendMessage() {
  const text = inputEl.value.trim();
  if (!text || state.busy) return;

  state.busy = true;
  sendEl.disabled = true;

  append("user", text);

  inputEl.value = "";
  autoGrow();

  const typingId = appendTyping();

  try {
    const res = await fetch("/api/chat", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        message: text,
        history: state.history,
        conversation_id: state.conversationId
      })
    });

    const data = await res.json();
    removeTyping(typingId);

    if (!res.ok) {
      append("assistant", data && data.error ? String(data.error) : "Hiba");
    } else {
      const reply = String(data.reply || "");
      append("assistant", reply);

      state.conversationId = String(data.conversation_id || state.conversationId);
      localStorage.setItem("conversation_id", state.conversationId);

      state.history.push({ role: "user", content: text });
      state.history.push({ role: "assistant", content: reply });
      if (state.history.length > 40) state.history = state.history.slice(-40);
    }
  } catch (e) {
    removeTyping(typingId);
    append("assistant", "Kapcsolódási hiba");
  } finally {
    state.busy = false;
    sendEl.disabled = inputEl.value.trim().length === 0;
  }
}

if ("serviceWorker" in navigator) {
  window.addEventListener("load", () => {
    navigator.serviceWorker.register("/static/sw.js");
  });
}
