"$VENV_PY" -m pip install -r requirements.txt

MODAL_CMD="$VENV_PY -m modal"

TOKEN_OK=0
if [ -n "${MODAL_TOKEN_ID:-}" ] && [ -n "${MODAL_TOKEN_SECRET:-}" ]; then
  TOKEN_OK=1
else
  if "$MODAL_CMD" config show --no-redact >/tmp/modal_config_show 2>/dev/null; then
    if grep -qE 'token_id\s*=' /tmp/modal_config_show && grep -qE 'token_secret\s*=' /tmp/modal_config_show; then
      TOKEN_OK=1
    fi
  fi
fi

if [ "$TOKEN_OK" -eq 0 ]; then
  MODAL_TOKEN_ID=""
  MODAL_TOKEN_SECRET=""
  read -r -p "MODAL_TOKEN_ID: " MODAL_TOKEN_ID || true
  read -r -s -p "MODAL_TOKEN_SECRET: " MODAL_TOKEN_SECRET || true
  echo
  MODAL_TOKEN_ID="${MODAL_TOKEN_ID:-}"
  MODAL_TOKEN_SECRET="${MODAL_TOKEN_SECRET:-}"
  if [ -z "$MODAL_TOKEN_ID" ] || [ -z "$MODAL_TOKEN_SECRET" ]; then
    echo "Modal token adatok hiányoznak."
    exit 1
  fi
  "$MODAL_CMD" token set --token-id "$MODAL_TOKEN_ID" --token-secret "$MODAL_TOKEN_SECRET"
fi

echo "Deploy-oljuk a Modal app-ot (modal_app.py)..."
"$MODAL_CMD" deploy modal_app.py

echo "Indítjuk a Flask app-ot (main.py) gunicorn-nal..."
exec "$VENV_PY" -m gunicorn -w 1 -k gthread -b 0.0.0.0:8080 main:app --threads 8 --timeout 0
